from pwn import *

def test_input(r, cmd):
    r.sendlineafter(b"Choice > ", b"1")
    r.sendlineafter(b"Command >", cmd.encode())
    try:
        result = r.recvuntil(b"Choice > ", timeout=1)
        return result.decode(errors='ignore')
    except:
        return "Timeout or connection closed"

def main():
    # List of commands to test
    commands = [
        "x=1",
        "a=a",
        "_=1",
        "__",
        "help",
        "sys"
    ]

    for cmd in commands:
        print(f"\nTesting command: {cmd}")
        print("-" * 40)

        # Connect for each test to get fresh environment
        try:
            r = remote('misc.chal.csaw.io', 9999)
            result = test_input(r, cmd)
            print(f"Response:\n{result}")
        except Exception as e:
            print(f"Error: {e}")
        finally:
            try:
                r.close()
            except:
                pass

if __name__ == "__main__":
    main()
